          "correctAnswer": 1,
          "explanation": "<b>Dịch nghĩa:</b> Thiệp mời tham dự buổi lễ đã được gửi đến hòm thư.\n<br><br><b>Giải thích:</b> Hậu tố 「〜状」（〜じょう: trạng) dùng để chỉ các loại giấy tờ, thư từ trang trọng: 「招待状」（しょうたいじょう: thư mời, thiệp mời).\n<br><br><i>Phân tích các phương án:</i><br>• 1. <b>状</b>: Đúng, ghép với 招待 tạo thành 招待状 (thiệp mời, giấy mời). Các từ tương tự: 案内状, 礼状.<br>• 2. <b>紙</b>: Giấy (かみ / し), không dùng làm hậu tố cho thư mời.<br>• 3. <b>書</b>: Thư/sách, dùng cho văn bản như 契約書 (bản hợp đồng), 報告書 (bản báo cáo).<br>• 4. <b>票</b>: Phiếu, dùng cho vé hoặc phiếu bầu như 投票 (bỏ phiếu), 伝票 (hóa đơn)."
