          "correctAnswer": 4,
          "explanation": "<b>Dịch nghĩa:</b> Anh ấy không bao giờ biết sợ thất bại mà thái độ luôn luôn quả cảm đương đầu trước mọi khó khăn thử thách quả là điều vô cùng đáng khâm phục.\n<br><br><b>Giải thích:</b> Thứ tự ghép câu hoàn chỉnh: 彼は失敗を<b>【恐れる (1)】 【ことなく (2)】 【★常に (4)】 【どんな困難にも (3)】</b> 果敢に挑戦し続ける姿勢が素晴らしい。\n<br>Cấu trúc 「V-る + ことなく」（không hề... mà làm gì), liên kết cụm 「恐れることなく」(không hề sợ hãi), tiếp theo là phó từ 「常に」(luôn luôn) và 「どんな困難にも果敢に挑戦し続ける」(quả cảm tiếp tục thử thách trước mọi khó khăn).\n<br><br><i>Phân tích các phương án:</i><br>• 1. <b>恐れる</b>: Đi sau 失敗を để tạo thành 失敗を恐れる.<br>• 2. <b>ことなく</b>: Đi sau 恐れる tạo thành 恐れることなく.<br>• 3. <b>どんな困難にも</b>: Đi trước 果敢に挑戦し続ける.<br>• 4. <b>常に</b>: Vị trí ngôi sao ★ (vị trí thứ 3), phó từ bổ nghĩa tần suất liên tục.<br><b>Thứ tự đúng:</b> 1 &rarr; 2 &rarr; <b>4 (★)</b> &rarr; 3. Do đó đáp án chọn là <b>4</b>."
