          "correctAnswer": 2,
          "explanation": "<b>Dịch nghĩa:</b> Không hề bị lung lay hay chi phối bởi ý kiến của những người xung quanh, anh ấy luôn kiên định giữ vững niềm tin của bản thân.\n<br><br><b>Giải thích:</b> Động từ 「左右する」（さゆうする）khi chia ở thể bị động 「左右される」（さゆうされる）mang nghĩa là bị chi phối, bị làm cho lung lay, dao động (周囲の意見に左右されない: không bị lung lay bởi ý kiến xung quanh).\n<br><br><i>Phân tích các phương án:</i><br>• 1. <b>誘惑</b>: Dụ dỗ, quyến rũ (thường đi với 誘惑に負ける: đầu hàng cám dỗ).<br>• 2. <b>左右</b>: Đúng, bị chi phối, làm ảnh hưởng (意見に左右されず).<br>• 3. <b>拘束</b>: Trói buộc thể xác, hạn chế tự do thời gian (thường đi với 時間を拘束される).<br>• 4. <b>制御</b>: Điều khiển, kiểm soát máy móc hoặc cảm xúc (感情を制御する)."
