          "type": "grammar",
          "question": "皆さんの前でお話しできる機会をいただき、心より光栄に（　　）。",
          "options": [
            "存じます",
            "申します",
            "申し上げます",
            "ございます"
          ],
          "correctAnswer": 1,
          "explanation": "<b>Dịch nghĩa:</b> Được nhận cơ hội quý báu để phát biểu trước toàn thể quý vị ngày hôm nay, tôi xin được bày tỏ lòng vinh hạnh tận đáy lòng.\n<br><br><b>Giải thích kính ngữ:</b> Khiêm nhường ngữ (Kenjougo) của động từ 「思う」（omou: nghĩ, cảm thấy) là 「存じる」（zonjiru). Trong bối cảnh phát biểu trang trọng, diễn đạt \"tôi cảm thấy vinh hạnh\" nói chuẩn lễ nghi là 「光栄に存じます」（こうえいにぞんじます).\n<br><br><i>Phân tích các phương án:</i><br>• 1. <b>存じます</b>: Đúng, khiêm nhường ngữ chuẩn của と思います (光栄に存じます).<br>• 2. <b>申します</b>: Khiêm nhường ngữ của 言う (nói: 田中と申します).<br>• 3. <b>申し上げます</b>: Khiêm nhường ngữ dùng cho hành động hướng tới đối phương (お礼を申し上げます, お詫び申し上げます), không đi với cảm xúc nội tâm 光栄に.<br>• 4. <b>ございます</b>: Thể lịch sự của あります, không thay thế cho động từ chỉ tâm trạng 思う."
